'use strict';
// All interactions on this concept page are local demos, with no purchases or network actions.
const $ = selector => document.querySelector(selector);
const dialog = $('#detail');
let toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function showDetail(title,paragraphs){$('#dialog-title').textContent=title;$('#dialog-body').replaceChildren(...paragraphs.map(text=>{const p=document.createElement('p');p.textContent=text;return p}));dialog.showModal()}
$('.close').onclick=()=>dialog.close();$('#dialog-done').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const games={
 'Hollow Tides':{genre:'Co-op · Survival',price:'199 kr',description:'Explore a changing coastline with up to four friends. Gather supplies and build a home before the tide returns.',times:['1 hour','2 hours','Open evening']},
 'Kintsugi Protocol':{genre:'Puzzle · Story',price:'149 kr',description:'Piece together a fractured signal in a story told through short, thoughtful puzzles.',times:['30 min','1 hour','2 hours','Open evening']},
 'Neon Orchard':{genre:'Cozy · Builder',price:'Free',description:'Grow a luminous orchard at your own pace. A cozy world for a short break or a long evening.',times:['30 min','1 hour','2 hours','Open evening']},
 'Ashen Meridian':{genre:'Action RPG',price:'399 kr',description:'Cross a vivid frontier and discover new paths through an atmospheric action RPG.',times:['2 hours','Open evening']}
};
let selectedTime='2 hours';
function filterGames(){const query=$('#search-input').value.toLowerCase().trim();let count=0;document.querySelectorAll('[data-game]').forEach(card=>{const name=card.dataset.game,g=games[name];const cozy=query.includes('cozy'),short=query.includes('30 min');const text=(name+' '+g.genre).toLowerCase();const matches=!query||(cozy&&text.includes('cozy'))||(short&&g.times.includes('30 min'))||text.includes(query);card.hidden=!(matches&&g.times.includes(selectedTime));if(!card.hidden)count++});$('#empty').hidden=count>0}
document.querySelectorAll('[data-time]').forEach(button=>button.onclick=()=>{selectedTime=button.dataset.time;document.querySelectorAll('[data-time]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});$('#session-caption').textContent=selectedTime==='Open evening'?'A whole evening. A world of possibilities.':'Games that fit your '+selectedTime+' session';filterGames()});
$('#search-input').addEventListener('input',filterGames);
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#search-input').focus()}});
document.querySelectorAll('[data-game]').forEach(card=>card.onclick=()=>{const g=games[card.dataset.game];showDetail(card.dataset.game,[g.genre+' · '+g.price,g.description,'This is a concept preview. No purchase or installation will be made.'])});
$('#wishlist').onclick=()=>{const saved=$('#wishlist').getAttribute('aria-pressed')!=='true';$('#wishlist').setAttribute('aria-pressed',String(saved));$('#wishlist').textContent=saved?'Wishlisted ✓':'Wishlist';notify(saved?'Voidrunner added to your wishlist':'Voidrunner removed from your wishlist')};
$('#trial').onclick=()=>showDetail('Your 15-minute Voidrunner trial',['Explore the first run before deciding what comes next. Your progress would carry over to the full game.','Cloud streaming is a proposed FMS feature. This preview does not launch a real game.']);
$('#why').onclick=()=>showDetail('Why these games?',['Session Match considers your available time, favorite genres and whether you want to play solo or with friends.','The match percentages and game activity are illustrative concept data. Choose a time above to explore the recommendations.']);
$('#credits').onclick=()=>showDetail('240 FMS Credits',['Your concept wallet balance is 240 FMS Credits.','The Time-Back Guarantee and credits system shown here are proposed FMS features, not a live commercial offer.']);
$('#profile').onclick=()=>showDetail('Your FMS space',['Welcome back, M. Your games, sessions and friends come together here.','Explore the original FMS homepage using the logo at the top of the sidebar.']);
$('#continue').onclick=()=>showDetail('Continue Neon Orchard',['Day 18 · 41 hours played · 12 of 30 achievements unlocked.','Your orchard is ready for another visit. Game launching is simulated in this concept preview.']);
document.querySelectorAll('[data-friend]').forEach(button=>button.onclick=()=>{if(button.dataset.action==='Invite'){notify('Demo invitation prepared for Aksel');button.textContent='Ready';return}showDetail(button.dataset.action==='Join'?'Join Eirik in Hollow Tides':'Watch Sander in Voidrunner',[button.dataset.action==='Join'?'Two of four party slots are open.':'Sander is on a solo run.','This is a local preview of the social experience. No connection or invitation is sent.'])});
document.querySelectorAll('[data-release]').forEach(button=>button.onclick=()=>showDetail(button.dataset.release,[button.querySelector('p').textContent,'Release timing is illustrative. Pre-orders and playtest registration are not active in this concept.']));
$('#upcoming').onclick=()=>showDetail('Upcoming on FMS',['Paper Kingdoms — Strategy · In 3 days','Static Bloom — Horror · In 2 weeks','Orbital Diner — Party · November','These are fictional games created for the FMS concept.']);
$('#download').onclick=()=>showDetail('Download manager',['Neon Orchard update · 68% complete · 84 MB/s','Download progress is simulated in this concept preview.']);
document.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>{const section=button.dataset.section;if(section==='Store'){showDetail('FMS Store',Object.entries(games).map(([name,g])=>name+' — '+g.genre+' · '+g.price))}else if(section==='Library'){showDetail('Your library',['Neon Orchard — Installed · Day 18 · 41 hours played','Voidrunner — 15-minute trial available'])}else{showDetail('Your friends',['Eirik — Hollow Tides · 2/4','Sander — Voidrunner · solo run','Aksel — In menu · free'])}});
